    def put(r, c, color, replace=False):
        if 0 <= r < h and 0 <= c < w and (replace or out[r][c] == 0):
            out[r][c] = color

    # A 1 grows a small hook toward the upper right.
    for r, c in pos.get(1, []):
        put(r-1, c+2, 1)
        put(r, c+1, 5)
        put(r, c+2, 5)

    # A 2 grows a five-cell horizontal line to its left.
    for r, c in pos.get(2, []):
        for cc, color in ((c-4, 2), (c-3, 5), (c-2, 5), (c-1, 5)):
            put(r, cc, color)

    # A 3 normally makes a downward ray ending in another 3.
    for r, c in pos.get(3, []):
        for rr, color in ((r+1, 5), (r+2, 5), (r+3, 3)):
            put(rr, c, color)

    # A 6 makes an upward vertical ray with a 6 at the far end.
    for r, c in pos.get(6, []):
        for rr in range(r-1, 0, -1):
            put(rr, c, 5)
        if r > 0:
            put(0, c, 6, replace=True)

    # Where a 2's center meets the vertical ray from a 6, mark the
    # crossing and continue diagonally down-left in color 4.
    for r2, c2 in pos.get(2, []):
        center = c2 - 2
        for r6, c6 in pos.get(6, []):
            if c6 == center and r2 < r6:
                put(r2, center, 4, replace=True)
                for k in range(1, h):
                    if r2+k < h and center-k >= 0:
