    seeds = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                seeds.setdefault(grid[r][c], []).append((r, c))

    def put(r, c, value, overwrite=False):
        if 0 <= r < h and 0 <= c < w and (overwrite or out[r][c] == 0):
            out[r][c] = value

    # Color 1: two 5s to the right, with a 1 above the far end.
    for r, c in seeds.get(1, []):
        put(r, c+1, 5)
        put(r, c+2, 5)
        put(r-1, c+2, 1)

    # Color 2: a horizontal bar with 2s at both ends.
    for r, c in seeds.get(2, []):
        for cc, value in ((c-4, 2), (c-3, 5), (c-2, 5), (c-1, 5)):
            put(r, cc, value)

    # Color 3: two 5s and a terminal 3 below the seed.
    for r, c in seeds.get(3, []):
        put(r+1, c, 5)
        put(r+2, c, 5)
        put(r+3, c, 3)

    # Color 6: extend upward to the top edge, ending in a 6.
    for r, c in seeds.get(6, []):
        for rr in range(r-1, 0, -1):
            put(rr, c, 5)
        if r > 0:
            put(0, c, 6, overwrite=True)

